// assignee_ids (+ unassigned) and created_at range. Sort:
// docs/list-contract.md, keys from leads usecase LeadsSortSpec; status and
// temperature sort by pipeline rank, name is the company or contact name.
func (q *Queries) ListLeadsInScope(ctx context.Context, arg ListLeadsInScopeParams) ([]Lead, error) {
	rows, err := q.db.Query(ctx, listLeadsInScope,
		arg.BrandID,
		arg.OrganizationIds,
		arg.Statuses,
		arg.TargetTypes,
		arg.Sources,
		arg.Temperatures,
		arg.AssigneeIds,
		arg.Unassigned,
		arg.CreatedFrom,
		arg.CreatedBefore,
		arg.Q,
		arg.Uuids,
		arg.FollowUpOnly,
		arg.ActorUserID,
		arg.FollowUpFrom,
		arg.FollowUpTo,
		arg.SortDesc,
		arg.SortKey,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Lead{}
	for rows.Next() {
		var i Lead
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.BrandID,
			&i.TargetType,
			&i.CustomerUserID,
			&i.VehicleID,
			&i.CandidateCompanyName,
			&i.CandidateContactName,
			&i.CandidatePhoneE164,
			&i.CandidateEmail,
			&i.CountryID,
			&i.ProvinceID,
			&i.DistrictID,
			&i.Source,
			&i.Temperature,
			&i.Status,
			&i.LostReason,
			&i.FollowUpDate,
			&i.AssigneeUserID,
			&i.Notes,
			&i.WonRefType,
			&i.WonRefID,
			&i.CreatedByUserID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

